// Original, code-drawn illustrations. All graphics are decorative; link text names each game.
const svg = (body, viewBox = '0 0 600 360') => `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${viewBox}" aria-hidden="true" focusable="false">${body}</svg>`;
const spark = (x, y, size = 12, fill = '#f8d975') => `<path d="M${x} ${y-size} Q${x} ${y} ${x+size} ${y} Q${x} ${y} ${x} ${y+size} Q${x} ${y} ${x-size} ${y} Q${x} ${y} ${x} ${y-size}" fill="${fill}"/>`;
const cloud = (x,y,s=1,color='#fffdf2') => `<g transform="translate(${x} ${y}) scale(${s})" fill="${color}"><path d="M0 25C-5 7 18-3 31 11C38-11 70-10 77 11C96 2 116 18 105 32H1Z"/></g>`;
const envelope = (x,y,s=1,rotate=-12) => `<g transform="translate(${x} ${y}) rotate(${rotate}) scale(${s})"><rect x="-46" y="-31" width="92" height="62" rx="10" fill="#ffdc82"/><path d="M-43-25L0 6L43-25M-44 26L-15 1M44 26L15 1" fill="none" stroke="#bc8b37" stroke-width="3" stroke-linejoin="round"/><circle cx="24" cy="-12" r="7" fill="#ef947c"/></g>`;

