function bridgeArt() {
  return svg(`<rect width="600" height="360" fill="#cbe2ee"/><circle cx="470" cy="75" r="34" fill="#ffdf88"/>${cloud(50,55,.8)}${cloud(378,130,1.1)}${cloud(200,272,.75,'#b7d6e3')}<path d="M0 290C92 232 170 289 242 250s129-12 207-40 109 15 151-5V360H0Z" fill="#b4d2da" opacity=".65"/><ellipse cx="177" cy="295" rx="95" ry="15" fill="#92b6b9" opacity=".4"/><ellipse cx="436" cy="266" rx="88" ry="13" fill="#92b6b9" opacity=".35"/><g><path d="M74 205L178 236L268 206L238 271L183 294L118 268Z" fill="#a49b72"/><path d="M74 205L178 236L183 294L118 268Z" fill="#b9aa7d"/><ellipse cx="171" cy="204" rx="97" ry="34" fill="#74985e"/><ellipse cx="171" cy="196" rx="97" ry="32" fill="#d9ed9d"/></g><g><path d="M349 171L436 198L520 174L493 235L438 268L381 232Z" fill="#9b9470"/><path d="M349 171L436 198L438 268L381 232Z" fill="#b1a17b"/><ellipse cx="435" cy="173" rx="86" ry="30" fill="#74985e"/><ellipse cx="435" cy="166" rx="86" ry="29" fill="#d9ed9d"/></g><path d="M229 193L394 164L399 181L234 211Z" fill="#c47158"/><path d="M229 185L394 156L399 170L234 201Z" fill="#f09b7f"/><path d="M251 181l5 14m24-19 5 14m24-19 5 14m24-19 5 14m24-19 5 14" stroke="#d07d62" stroke-width="3"/><g transform="translate(163 157)"><ellipse cy="35" rx="22" ry="6" fill="#b8cf86"/><rect x="-16" y="-5" width="32" height="37" rx="10" fill="#fff7df"/><circle cy="-13" r="19" fill="#f1c66c"/><circle cx="-6" cy="-14" r="2.4" fill="#234740"/><circle cx="6" cy="-14" r="2.4" fill="#234740"/><path d="M-5-5q5 5 10 0" fill="none" stroke="#234740" stroke-width="2"/></g><path d="M446 137V91" stroke="#355e49" stroke-width="4"/><path d="M448 93L476 101L448 114Z" fill="#ed947c"/>${spark(304,112,11,'#fff9df')}<path d="M94 171l-6-18m10 16 3-21m6 22 9-15M474 149l8-17m-1 20 13-9" stroke="#759b60" stroke-width="4" stroke-linecap="round"/>`);
}
function lightsArt() {
  let lamps='';
  for(let y=0;y<4;y++)for(let x=0;x<4;x++) {
    const lit=[0,2,5,6,8,9,11,14].includes(y*4+x);
    lamps+=`<g transform="translate(${201+x*56} ${92+y*56})"><rect x="-21" y="-21" width="43" height="43" rx="12" fill="${lit?'#ffe29a':'#8174a2'}"/><circle cy="-2" r="10" fill="${lit?'#fff9d8':'#a69bbd'}"/><path d="M-5 10H5M-4 14H4" stroke="${lit?'#bf944b':'#6a5b89'}" stroke-width="3" stroke-linecap="round"/></g>`;
  }
  return svg(`<rect width="600" height="360" fill="#e8e1f0"/><circle cx="488" cy="80" r="75" fill="#ded2e9"/><circle cx="103" cy="286" r="72" fill="#ded2e9"/><ellipse cx="301" cy="304" rx="162" ry="21" fill="#cec2dd"/><g transform="rotate(-7 300 174)"><rect x="159" y="54" width="262" height="258" rx="32" fill="#695c83"/><rect x="159" y="40" width="262" height="258" rx="32" fill="#9b8bb2"/><rect x="174" y="55" width="232" height="227" rx="21" fill="#796991"/>${lamps}</g>${spark(109,117,16,'#b7a6c9')}${spark(471,249,21,'#c7b8d5')}${spark(438,53,9,'#f5d681')}<circle cx="107" cy="190" r="6" fill="#b7a6c9"/><circle cx="499" cy="184" r="5" fill="#b7a6c9"/><path d="M79 251l-10 6m14 5-5 10M469 123l14-5m-12 17 13 4" stroke="#b3a1c4" stroke-width="4" stroke-linecap="round"/>`);
}
